#define TPP_HAVE_STRING_ESCAPE_OCT ((TPP_HAVE_LEXER_DECODESTRING && TPP_HAVE_STRING_ESCAPE && TPP_HAVE_PROFILE_NOT_MINIMAL) ? (TPP_HAVE_PROFILE_ALL ? TPP_COMMON_CONF_EXT1 : 1) : 0) /* "-fstring-escape-oct" */
