#define TPP_CASE_TPP_TOK_FLOAT /* nothing */
#define TPP_TOK_ISFLOAT(x)     0
#endif /* !TPP_HAVE_TOK_FLOAT */

	/* Any kind of number-like token */
#define TPP_CASE_TPP_TOK_NUMBER \
	TPP_CASE_TPP_TOK_INT        \
