#else /* TPP_HAVE_FILE_KEEPPOS */
#define _tpp_file_init_io_keep(self) /* nothing */
#endif /* !TPP_HAVE_FILE_KEEPPOS */
			tpp_io_handle    TPP_INTERNAL(tff_file);     /* [owned_if(!TPP_FILE_FLAGS_NOCLOSE)] Underlying I/O file */
