#define tpp_hooks_del_isfloatsuffix(self, lexer, cb)            _tpp_hooklist2_del((TPP_INTERNAL(tpp_hooklist2) **)&(self)->TPP_INTERNAL(th_isfloatsuffix), (void (*)(void))(cb), lexer)
